-- Avisos propios, recursos reales, paginación completa y lectura explícita.
begin;
set local statement_timeout='45s';
do $$
declare trainer uuid:=gen_random_uuid(); pupil uuid:=gen_random_uuid(); other uuid:=gen_random_uuid();
 rel uuid:=gen_random_uuid(); message uuid:=gen_random_uuid(); next_message uuid:=gen_random_uuid();
 form_id uuid; form_delivery uuid:=gen_random_uuid(); battery uuid; assessment uuid:=gen_random_uuid();
 exercise uuid; template uuid; scheduled uuid:=gen_random_uuid(); retired uuid:=gen_random_uuid(); execution uuid;
 clip uuid; clip_video uuid:=gen_random_uuid(); claim uuid:=gen_random_uuid(); feedback uuid:=gen_random_uuid();
 message_notice uuid; assignment_notice uuid; retired_notice uuid; feedback_notice uuid; form_notice uuid; assessment_notice uuid;
 scratch_relation uuid:=gen_random_uuid(); scratch_notice uuid:=gen_random_uuid(); scratch_trainer uuid:=gen_random_uuid();
 payload jsonb; j jsonb; page jsonb; last_item jsonb; count_before integer; stamp timestamptz;
begin
 insert into auth.users(id,email) values(trainer,trainer||'@student-notices.invalid'),(pupil,pupil||'@student-notices.invalid'),(other,other||'@student-notices.invalid');
 insert into auth.mfa_factors(id,user_id,factor_type,status,created_at,updated_at) values(gen_random_uuid(),trainer,'totp','verified',now(),now());
 insert into public.admin_permissions(user_id) values(other);
 insert into public.trainer_access(trainer_id,enabled,client_limit,last_reason) values(trainer,true,1,'Fixture avisos');
 insert into public.trainer_client_relations(id,trainer_id,client_id,accepted_at) values(rel,trainer,pupil,now());
 perform set_config('request.jwt.claim.sub',pupil::text,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',pupil,'role','authenticated','aal','aal1')::text,true);
 set local role authenticated;
 j:=public.get_my_trainer_notices(pupil);
 if j->'items'<>'[]'::jsonb or (j->>'unread_count')::integer<>0 or j->'resources'<>'{"has_forms":false,"has_assessments":false,"has_conversations":false,"has_technique":false,"has_assigned_workouts":false,"conversation_relation_id":null}'::jsonb then raise exception 'Vínculo vacío crea contenido'; end if;
 if public.list_my_trainer_technique(pupil)->'items'<>'[]'::jsonb then raise exception 'Índice técnico vacío incorrecto'; end if;
 perform set_config('request.jwt.claim.sub',trainer::text,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',trainer,'role','authenticated','aal','aal2')::text,true);
 form_id:=public.save_trainer_form(gen_random_uuid(),'{"title":"Formulario privado","description":null,"questions":[{"id":"ok","position":0,"prompt":"¿Todo bien?","type":"yesNo","required":true,"options":[]}]}');
 perform public.assign_trainer_form(form_delivery,rel,form_id,current_date);
 perform public.assign_trainer_form(form_delivery,rel,form_id,current_date);
 battery:=public.save_trainer_assessment(gen_random_uuid(),'{"title":"Prueba privada","tests":[{"id":"run","source":"custom","name":"Recorrido","unit":"seconds","direction":"lower","resolution":0.01,"instructions":"Recorre el trazado y registra la marca real.","max_attempts":1,"retry_policy":"none"}]}');
 perform public.assign_trainer_assessment(assessment,rel,battery,current_date);
 perform public.assign_trainer_assessment(assessment,rel,battery,current_date);
 exercise:=public.save_trainer_exercise(gen_random_uuid(),'{"name":"Ejercicio avisos","description":"Fixture","muscle_groups":["espalda"],"equipment":["barra"],"difficulty":"intermedio","exercise_type":"repeticiones"}');
 payload:=jsonb_build_object('name','Sesión avisos','blocks',jsonb_build_array(jsonb_build_object('name','Fuerza','format','straight_sets','rounds',1,'rest_after_seconds',0,'exercises',jsonb_build_array(jsonb_build_object('exercise_id',exercise,'sets',jsonb_build_array(jsonb_build_object('target_reps',8,'rest_after_seconds',60)))))));
 template:=public.save_trainer_workout(gen_random_uuid(),payload);
 perform public.assign_trainer_workout(scheduled,rel,template,current_date,null);
 perform public.assign_trainer_workout(scheduled,rel,template,current_date,null);
 perform public.send_trainer_message(message,rel,'Texto privado que no pertenece al feed',null);
 perform public.send_trainer_message(message,rel,'Texto privado que no pertenece al feed',null);
 perform set_config('request.jwt.claim.sub',pupil::text,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',pupil,'role','authenticated','aal','aal1')::text,true);
 j:=public.get_my_trainer_notices(pupil);
 if jsonb_array_length(j->'items')<>4 or (j->>'unread_count')::integer<>4 then raise exception 'Duplica avisos de reintentos'; end if;
 if j::text like '%Texto privado%' or j::text like '%answers%' or j::text like '%body%' then raise exception 'Copia datos privados al feed'; end if;
 if not (j->'resources'->>'has_forms')::boolean or not (j->'resources'->>'has_assessments')::boolean or not (j->'resources'->>'has_conversations')::boolean or not (j->'resources'->>'has_assigned_workouts')::boolean or j->'resources'->>'conversation_relation_id'<>rel::text then raise exception 'Existencia recursos incorrecta'; end if;
 select (value->>'id')::uuid into message_notice from jsonb_array_elements(j->'items') where value->>'kind'='message';
 select (value->>'id')::uuid into assignment_notice from jsonb_array_elements(j->'items') where value->>'kind'='assignment';
 select (value->>'id')::uuid into form_notice from jsonb_array_elements(j->'items') where value->>'kind'='form';
 select (value->>'id')::uuid into assessment_notice from jsonb_array_elements(j->'items') where value->>'kind'='assessment';
 if public.resolve_my_trainer_notice(pupil,message_notice) is distinct from jsonb_build_object('kind','conversation','target_id',rel) then raise exception 'Destino conversación incorrecto'; end if;
 if public.resolve_my_trainer_notice(pupil,assignment_notice)->>'scheduled_date'<>current_date::text then raise exception 'Pierde fecha de pauta'; end if;
 if (public.get_my_trainer_notices(pupil)->>'unread_count')::integer<>4 then raise exception 'Resolver marca leído'; end if;
 perform public.send_trainer_message(gen_random_uuid(),rel,'Respuesta del alumno',null);
 if (public.get_my_trainer_notices(pupil)->>'unread_count')::integer<>4 then raise exception 'Avisa al alumno de su mensaje propio'; end if;
 perform public.ack_my_trainer_notice(pupil,message_notice);
 perform public.ack_my_trainer_notice(pupil,message_notice);
 if (public.get_my_trainer_notices(pupil)->>'unread_count')::integer<>3 then raise exception 'Lectura no idempotente'; end if;
 reset role;
 select read_at into stamp from trainer_private.student_notices where id=message_notice;
 update public.trainer_assignments set planning_revision=planning_revision+1 where scheduled_id=scheduled;
 update public.trainer_assignments set result_revision=result_revision+1 where scheduled_id=scheduled;
 set local role authenticated;
 if (public.get_my_trainer_notices(pupil)->>'unread_count')::integer<>4 then raise exception 'Cambiar resultado produce aviso o revisión no avisa'; end if;
 execution:=public.start_scheduled_workout(scheduled);
 j:=public.list_my_trainer_technique(pupil);
 if jsonb_array_length(j->'items')<>1 or j->'items'->0->>'execution_id'<>execution::text then raise exception 'No ofrece enviar técnica sin feedback'; end if;
 if not (public.get_my_trainer_notices(pupil)->'resources'->>'has_technique')::boolean then raise exception 'Resumen no detecta técnica propia'; end if;
 clip:=public.reserve_exercise_video_upload('client_technique',gen_random_uuid(),42,'fixture.b-cdn.net',1000000,scheduled,execution,null);
 reset role;
 perform public.claim_exercise_video_creation(clip,claim);
 perform public.complete_exercise_video_creation(clip,claim,clip_video);
 update public.exercise_video_assets set status='ready',duration_seconds=90,playback_bytes=1000000,provider_storage_bytes=2000000 where id=clip;
 set local role authenticated;
 perform set_config('request.jwt.claim.sub',trainer::text,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',trainer,'role','authenticated','aal','aal2')::text,true);
 perform public.add_trainer_video_feedback(feedback,clip,1,'Corrección técnica privada');
 perform public.add_trainer_video_feedback(feedback,clip,1,'Corrección técnica privada');
 perform public.assign_trainer_workout(retired,rel,template,current_date+1,null);
 perform public.send_trainer_message(next_message,rel,'Mensaje posterior a lectura',null);
 for i in 1..51 loop perform public.send_trainer_message(gen_random_uuid(),rel,'Paginación',null); end loop;
 perform set_config('request.jwt.claim.sub',pupil::text,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',pupil,'role','authenticated','aal','aal1')::text,true);
 j:=public.get_my_trainer_notices(pupil,null,null,'message');
 if jsonb_array_length(j->'items')<>50 or not (j->>'has_more')::boolean or (j->>'unread_count')::integer<>58 then raise exception 'Contador parcial o página incorrecta: %',j; end if;
 if exists(select 1 from jsonb_array_elements(j->'items') where value->>'kind'<>'message') then raise exception 'Filtro mezcla tipos'; end if;
 last_item:=j->'items'->49;
 page:=public.get_my_trainer_notices(pupil,(last_item->>'created_at')::timestamptz,(last_item->>'id')::uuid,'message');
 if jsonb_array_length(page->'items')<>3 or (page->>'has_more')::boolean then raise exception 'Paginar pierde mensajes empatados'; end if;
 if exists(select 1 from jsonb_array_elements(j->'items') a join jsonb_array_elements(page->'items') b on a.value->>'id'=b.value->>'id') then raise exception 'Repite página'; end if;
 perform public.ack_my_trainer_notice(pupil,message_notice);
 if (public.get_my_trainer_notices(pupil)->>'unread_count')::integer<>58 then raise exception 'Lectura antigua consume evento nuevo'; end if;
 j:=public.get_my_trainer_notices(pupil,null,null,'techniqueFeedback');
 feedback_notice:=(j->'items'->0->>'id')::uuid;
 if jsonb_array_length(j->'items')<>1 or public.resolve_my_trainer_notice(pupil,feedback_notice)->>'target_id'<>execution::text then raise exception 'Feedback duplicado o destino incorrecto'; end if;
 j:=public.get_my_trainer_notices(pupil,null,null,'assignment');
 select (value->>'id')::uuid into retired_notice from jsonb_array_elements(j->'items') where public.resolve_my_trainer_notice(pupil,(value->>'id')::uuid)->>'target_id'=retired::text;
 begin perform public.get_my_trainer_notices(pupil,now(),null); raise exception 'Acepta cursor incompleto'; exception when invalid_parameter_value then null; end;
 begin perform public.get_my_trainer_notices(pupil,null,null,'unknown'); raise exception 'Acepta tipo abierto'; exception when invalid_parameter_value then null; end;
 begin perform public.get_my_trainer_notices(other); raise exception 'Acepta expected_owner ajeno'; exception when insufficient_privilege then null; end;
 perform set_config('request.jwt.claim.sub',other::text,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',other,'role','authenticated','aal','aal2')::text,true);
 if public.get_my_trainer_notices(other)->'items'<>'[]'::jsonb or public.list_my_trainer_technique(other)->'items'<>'[]'::jsonb then raise exception 'ADMIN ve avisos/técnica ajenos'; end if;
 begin perform public.ack_my_trainer_notice(other,message_notice); raise exception 'Otro acusa lectura'; exception when insufficient_privilege then null; end;
 begin perform public.resolve_my_trainer_notice(other,message_notice); raise exception 'Otro resuelve'; exception when insufficient_privilege then null; end;
 begin perform public.list_my_trainer_technique(pupil); raise exception 'Otro consulta índice'; exception when insufficient_privilege then null; end;
 if has_table_privilege('authenticated','trainer_private.student_notices','SELECT') or has_table_privilege('authenticated','trainer_private.student_notices','INSERT') or has_function_privilege('anon','public.get_my_trainer_notices(uuid,timestamptz,uuid,text)','EXECUTE') or has_function_privilege('authenticated','trainer_private.student_notice_target(uuid)','EXECUTE') then raise exception 'Grants abren bandeja/helpers'; end if;
 perform set_config('request.jwt.claim.sub',pupil::text,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',pupil,'role','authenticated','aal','aal1','is_anonymous',true)::text,true);
 begin perform public.get_my_trainer_notices(pupil); raise exception 'Anónimo accede'; exception when insufficient_privilege then null; end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',pupil,'role','authenticated','aal','aal1')::text,true);
 perform public.end_trainer_relation(rel);
 if public.resolve_my_trainer_notice(pupil,retired_notice) is not null then raise exception 'Pauta retirada sin ejecución conserva destino'; end if;
 if public.resolve_my_trainer_notice(pupil,message_notice)->>'target_id'<>rel::text or public.resolve_my_trainer_notice(pupil,form_notice)->>'target_id'<>form_delivery::text or public.resolve_my_trainer_notice(pupil,assessment_notice)->>'target_id'<>assessment::text then raise exception 'Baja pierde histórico'; end if;
 if (public.get_trainer_form_submission(form_delivery)->>'can_respond')::boolean or public.get_trainer_assessment_delivery(assessment)->>'status'<>'withdrawn' then raise exception 'Baja ofrece acción inválida'; end if;
 if jsonb_array_length(public.list_my_trainer_technique(pupil)->'items')<>1 then raise exception 'Baja oculta historial técnico'; end if;
 perform public.set_client_technique_shared(gen_random_uuid(),clip,false);
 if public.resolve_my_trainer_notice(pupil,feedback_notice)->>'target_id'<>execution::text then raise exception 'Retirar compartición oculta feedback propio'; end if;
 reset role;
 if (select read_at from trainer_private.student_notices where id=message_notice) is distinct from stamp then raise exception 'Reintento cambia fecha de lectura'; end if;
 if not (select relrowsecurity from pg_class where oid='trainer_private.student_notices'::regclass) then raise exception 'Falta RLS'; end if;
 delete from trainer_private.video_feedback where id=feedback;
 set local role authenticated;
 if public.resolve_my_trainer_notice(pupil,feedback_notice) is not null then raise exception 'Destino borrado resucita'; end if;
 reset role;
 -- Los avisos no añaden un bloqueo al borrado físico de una relación vacía.
 insert into public.trainer_client_relations(id,trainer_id,client_id,accepted_at,ended_at) values(scratch_relation,trainer,pupil,now()-interval '2 days',now()-interval '1 day');
 insert into trainer_private.student_notices(id,owner_id,relation_id,kind,source_id) values(scratch_notice,pupil,scratch_relation,'message',gen_random_uuid());
 select count(*) into count_before from trainer_private.student_notices where relation_id=rel;
 delete from public.trainer_client_relations where id=scratch_relation;
 if exists(select 1 from trainer_private.student_notices where id=scratch_notice) or (select count(*) from trainer_private.student_notices where relation_id=rel)<>count_before then raise exception 'Cascada bloquea borrado o afecta relación ajena'; end if;
 insert into auth.users(id,email) values(scratch_trainer,scratch_trainer||'@notice-delete.invalid');
 insert into public.trainer_client_relations(id,trainer_id,client_id,accepted_at,ended_at)
  values(scratch_relation,scratch_trainer,pupil,now()-interval '2 days',now()-interval '1 day');
 insert into trainer_private.student_notices(id,owner_id,relation_id,kind,source_id)
  values(scratch_notice,pupil,scratch_relation,'message',gen_random_uuid());
 delete from auth.users where id=scratch_trainer;
 if exists(select 1 from trainer_private.student_notices where id=scratch_notice)
  or (select count(*) from trainer_private.student_notices where relation_id=rel)<>count_before then raise exception 'Borrar preparador bloquea cascada o afecta avisos ajenos'; end if;
end $$;
select 'trainer_student_notices OK' as result;
rollback;
